import json
class Tracker:
    def __init__(self, books):
        self.books = books
    def add(self, title, pages):
        self.books.append({"title": title, "pages": pages})
    def total_pages(self):
        total = 0
        for book in self.books:
            total = total + book["pages"]
        return total
tracker = Tracker([{"title": "Sky", "pages": 20}, {"title": "Sea", "pages": 30}])
title = input()
try:
    pages = int(input())
except ValueError:
    print("Use whole-number pages")
else:
    if pages > 0:
        tracker.add(title, pages)
    else:
        print("Pages must be positive")
with open("books.json", "w") as saved:
    saved.write(json.dumps(tracker.books))
with open("books.json", "r") as saved:
    restored = Tracker(json.loads(saved.read()))
for book in restored.books:
    print(book["title"], book["pages"])
print("Total pages", restored.total_pages())
